import{_ as e}from"./chunks/fleet-tracking.BorPpiUb.js";import{_ as t,o as r,c as i,a2 as l}from"./chunks/framework.CWgsre3x.js";const f=JSON.parse('{"title":"Παρακολούθηση στόλου και τηλεματική","description":"","frontmatter":{},"headers":[],"relativePath":"el/integrations/live-tracking.md","filePath":"el/integrations/live-tracking.md"}'),n={name:"el/integrations/live-tracking.md"};function o(s,a,p,c,h,m){return r(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="παρακολουθηση-στολου-και-τηλεματικη" tabindex="-1">Παρακολούθηση στόλου και τηλεματική <a class="header-anchor" href="#παρακολουθηση-στολου-και-τηλεματικη" aria-label="Permalink to &quot;Παρακολούθηση στόλου και τηλεματική&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Προσχέδιο βάσει πηγαίου κώδικα · v0.7.9. Επιβεβαιώστε διαθεσιμότητα και δικαιώματα στην εγκεκριμένη έκδοση.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/fleet-tracking.png"><img src="'+e+'" alt="Fleet Tracking / Live Operations: ορόσημα κρατήσεων και αναθέσεις στόλου. Η οθόνη δηλώνει ότι οι εξωτερικοί πάροχοι GPS, πτήσεων και AIS παραμένουν ανενεργοί με ασφαλή αποκλεισμό."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Fleet Tracking / Live Operations: ορόσημα κρατήσεων και αναθέσεις στόλου. Η οθόνη δηλώνει ότι οι εξωτερικοί πάροχοι GPS, πτήσεων και AIS παραμένουν ανενεργοί με ασφαλή αποκλεισμό.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή. Έχουν καλυφθεί αναγνωριστικά στοιχεία.</p><h2 id="διαθεσιμοτητα" tabindex="-1">Διαθεσιμότητα <a class="header-anchor" href="#διαθεσιμοτητα" aria-label="Permalink to &quot;Διαθεσιμότητα&quot;">​</a></h2><p>Η ζωντανή παρακολούθηση απαιτεί ρυθμισμένο πάροχο τηλεματικής. Η έκδοση αναφοράς διαχωρίζει τα δοκιμαστικά δεδομένα από τις ζωντανές θέσεις και δεν αποδεικνύει λειτουργική σύνδεση GPS παραγωγής.</p><h2 id="διαδικασια-χειριστη" tabindex="-1">Διαδικασία χειριστή <a class="header-anchor" href="#διαδικασια-χειριστη" aria-label="Permalink to &quot;Διαδικασία χειριστή&quot;">​</a></h2><ol><li>Επιβεβαιώστε τον πάροχο και την εταιρική σύνδεση με εξουσιοδοτημένο διαχειριστή.</li><li>Βεβαιωθείτε ότι τα εμφανιζόμενα δεδομένα χαρακτηρίζονται ζωντανά και όχι προσομοιωμένα πριν από αποφάσεις ανάθεσης.</li><li>Αν η παρακολούθηση δεν είναι διαθέσιμη, χρησιμοποιήστε επιβεβαιωμένες αναθέσεις και άμεση επικοινωνία σύμφωνα με τις διαδικασίες της εταιρείας.</li></ol><p>Μην συμπεραίνετε πραγματική θέση οδηγού από δοκιμαστικό σημείο ή ώρα άφιξης από μη επαληθευμένη πηγή. Μη δημοσιεύετε στιγμιότυπα με προσωπικά στοιχεία θέσης οδηγών.</p><p>Δείτε <a href="/el/plus/fleet-management.html">Διαχείριση στόλου</a> και <a href="/el/plus/assignments.html">Ανάθεση οδηγού και οχήματος</a>.</p><h2 id="επιχειρησιακη-παρακολουθηση-v0-7-26" tabindex="-1">Επιχειρησιακή παρακολούθηση v0.7.26 <a class="header-anchor" href="#επιχειρησιακη-παρακολουθηση-v0-7-26" aria-label="Permalink to &quot;Επιχειρησιακή παρακολούθηση v0.7.26&quot;">​</a></h2><p>Το ιστορικό στιγμιότυπο είναι v0.7.11 και δεν απεικονίζει τη σημερινή δυνατότητα GPS. Ο κώδικας v0.7.26 υποστηρίζει τοπική γεωγραφική απεικόνιση και ταυτοποιημένες θέσεις οδηγών. Απαιτείται ρητή επιλογή κοινοποίησης και εξουσιοδότηση εντός βάρδιας· σημαντικές είναι φρεσκάδα, ακρίβεια και ανάκληση. Ο χειριστής ελέγχει περιοχή, σκέλος και τελευταία αναφορά. Παρωχημένη ή ελλιπής θέση δεν αποδεικνύει κίνηση. Η επιστροφή μπορεί να έχει διαφορετικό οδηγό.</p><p>Προαιρετικοί αδειοδοτημένοι χάρτες και εκτιμήσεις απαιτούν χωριστή ρύθμιση και αποδοχή. Εκκρεμούν φυσικός έλεγχος GPS κινητού και αυτόματη εξωτερική παρακολούθηση αφίξεων. Δείτε <a href="/el/integrations/maps-arrivals-setup.html">Ρύθμιση χαρτών</a> και <a href="/el/plus/arrival-intelligence.html">Αφίξεις</a>.</p>',16)])])}const u=t(n,[["render",o]]);export{f as __pageData,u as default};
